# `workspace.members`.

[workspace]
members = ["."]
resolver = "2"

[package]
name = "everbloom"
version = "0.1.0"
edition = "2024"

[lib]
crate-type = ["rlib"]

[[bin]]
name = "whisker-config"
path = "whisker.rs"
required-features = ["whisker-config"]
test = false
bench = false

