// subclasses at build time and emits the Host registration.

import PackageDescription

let package = Package(
    name: "shop-native",
    platforms: [.iOS(.v13), .macOS(.v13)],
    products: [
        .library(name: "ShopNative", targets: ["ShopNative"]),
    ],
    dependencies: [
        .package(url: "https://github.com/whiskerrs/whisker.git", exact: "0.1.19"),
    ],
    targets: [
        .target(
            name: "ShopNative",
            dependencies: [
                .product(name: "WhiskerModule", package: "whisker"),
                .product(name: "WhiskerRuntime", package: "whisker"),
            ],
            path: "ios/Sources/ShopNative",
