            observing: observing
        )
    }

    private func deliver(
        _ value: WhiskerValue,
        _ result: WhiskerModuleResult,
        _ resultData: UnsafeMutableRawPointer?
    ) {
        var raw = value.toRaw()
        result(resultData, &raw)
        WhiskerValue.releaseRaw(&raw)
    }
