//! ```
//!
//! ### Multiline
//!
//! ```ignore
//! Input(text: notes, multiline: true, lines: 4,
//!       placeholder: "Notes…",
//!       style: css!(min_height: px(96)))
//! ```
//!
//! ### Secure (password)
//!
//! ```ignore
//! Input(text: password, secure: true, placeholder: "Password")
//! ```
//!
//! ### Imperative handle
//!
//! ```ignore
//! let field = InputRef::new();
//! render! {
//!     View(style: css!(flex_direction: FlexDirection::Row)) {
//!         Input(text: text, input_ref: field.clone())
//!         Text(value: "Clear", on_tap: {
//!             let field = field.clone();
//!             move |_| field.clear()
//!         })
//!     }
//! }
//! ```
//!
//! ## Props
//!
//! | Prop               | Type                                  | Default       | Description |
//! |--------------------|---------------------------------------|---------------|-------------|
//! | `text`             | `RwSignal<String>`                    | —             | Two-way bound value. Updates on every keystroke. |
//! | `value`            | `Signal<String>`                      | —             | Controlled read (escape hatch; ignored if `text` is set). |
//! | `on_input`         | `Fn(String)`                          | —             | Fires every keystroke with the new full text. |
//! | `on_change`        | `Fn(String)`                          | —             | Fires when editing ends / value committed. |
//! | `on_focus`         | `Fn()`                                | —             | Field gained focus. |
//! | `on_blur`          | `Fn()`                                | —             | Field lost focus. |
//! | `on_submit`        | `Fn(String)`                          | —             | Return / done key pressed. |
//! | `placeholder`      | `Signal<String>`                      | `""`          | Placeholder text shown when empty. |
//! | `multiline`        | `bool`                                | `false`       | Single-line field vs multiline area. |
//! | `auto_size`        | `bool`                                | `false`       | Measure content at its layout width; respects min/max size and overrides `lines`. Otherwise the intrinsic height is one line, or `lines` when multiline. |
//! | `on_size_change`   | `Fn(InputSize)`                        | —             | Final size after padding, borders, and style constraints. |
//! | `lines`            | `u32`                                 | unset (`0`)   | Visible line count for the intrinsic height (multiline only). |
//! | `secure`           | `bool`                                | `false`       | Mask Input (password entry). |
//! | `editable`         | `bool`                                | `true`        | Allow editing. |
//! | `auto_focus`       | `bool`                                | `false`       | Focus + raise keyboard on mount. |
//! | `max_length`       | `u32`                                 | unset (`0`)   | Maximum character count. |
//! | `keyboard_type`    | [`KeyboardType`]                      | `Default`     | On-screen keyboard layout. |
//! | `return_key`       | [`ReturnKey`]                         | `Default`     | Return-key label / action. |
//! | `auto_capitalize`  | [`AutoCapitalize`]                    | `Sentences`   | Keyboard auto-capitalization (`None` for handles / emails). |
//! | `autocorrect`      | `bool`                                | `true`        | Automatic typo replacement (`false` for identifiers). |
//! | `spell_check`      | `bool`                                | `true`        | Spell-check underline / suggestion strip (`false` for identifiers). |
//! | `caret_color`      | `Signal<String>`                      | `""`          | Cursor color (CSS color string). |
//! | `placeholder_color`| `Signal<String>`                      | `"#999999"`   | Placeholder text color. |
//! | `selection_color`  | `Signal<String>`                      | `""`          | Selection-highlight color. |
//! | `style`            | `Style`                              | empty          | Structured Whisker CSS declarations. |
//! | `input_ref`        | [`InputRef`]                          | —             | Imperative handle (see [Methods](#methods)). |
//!
//! ## Styling
//!
//! Box layout and **text** styling flow through the standard `style:`
//! CSS cascade — `width` / `height` / `padding` / `border` /
//! `background-color` / `border-radius`, plus the text properties the
//! native field honors: `color`, `font-size`, `font-weight`,
//! `text-align`.
//!
//! The cursor / placeholder / selection colors are **explicit props**
//! ([`caret_color`](InputProps), [`placeholder_color`](InputProps),
//! [`selection_color`](InputProps)) rather than CSS, because the shared
//! style cascade only controls the module element's generic presentation;
//! it does not reach private subviews, so these
//! sub-element colors must be passed as attributes the native view
//! reads directly.
//!
//! ## Methods
//!
//! Hold an [`InputRef`], pass `input_ref:` to the component, then:
//!
//! - [`InputRef::focus`] — focus the field + raise the keyboard.
//! - [`InputRef::blur`] — resign focus + dismiss the keyboard.
//! - [`InputRef::clear`] — clear the text to empty.
//! - [`InputRef::set_value`] — replace the text imperatively.
//!
//! Read the current text from the bound `text` signal or from an input event.
//! Component commands are deliberately one-way and do not return state.
/// Element schema exported for generated Host bootstrap.
#[doc(hidden)]
pub fn __whisker_element_module_definition() -> whisker::ElementModuleDefinition {
    whisker::ElementModuleDefinition::new(
        env!("CARGO_PKG_NAME"),
        [native_input_schema::element_provider()],
    )
}

/// `whisker-input:Input` — a native text field with Leptos-style
/// two-way binding.
///
/// See the [crate docs](crate) for usage, the full prop table, and
/// styling notes.
#[allow(clippy::too_many_arguments)]
#[component]
pub fn input(
    /// Two-way bound value (headline API). Updates on every keystroke.
    text: Option<RwSignal<String>>,
    /// Controlled read (escape hatch). Ignored when `text` is set.
    value: Option<Signal<String>>,
    /// Fires every keystroke with the new full text.
    on_input: Option<Callback<String>>,
    /// Fires when editing ends / the value is committed.
    on_change: Option<Callback<String>>,
    /// Field gained focus.
    on_focus: Option<Callback<()>>,
    /// Field lost focus.
    on_blur: Option<Callback<()>>,
    /// Return / done key pressed; carries the current text.
    /// Web and Desktop also submit multiline inputs with Command/Ctrl + Enter.
    on_submit: Option<Callback<String>>,
    /// Placeholder text shown when the field is empty.
    placeholder: Option<Signal<String>>,
    /// Multiline area vs single-line field.
    #[prop(default = false)]
    multiline: bool,
    /// Measures content height under the current layout width; CSS min/max height still apply.
    #[prop(default = false)]
    auto_size: bool,
    /// Reports the final input border-box size after layout, in logical pixels.
    on_size_change: Option<Callback<InputSize>>,
    /// Fixed visible line count (multiline only); ignored when auto_size is enabled.
    lines: Option<u32>,
    /// Mask Input (password entry).
    #[prop(default = false)]
    secure: bool,
    /// Allow editing.
    #[prop(default = true)]
    editable: bool,
    /// Focus + raise the keyboard on mount.
    #[prop(default = false)]
    auto_focus: bool,
    /// Maximum character count.
    max_length: Option<u32>,
    /// On-screen keyboard layout.
    #[prop(default = KeyboardType::Default)]
    keyboard_type: KeyboardType,
    /// Return-key label / action.
    #[prop(default = ReturnKey::Default)]
    return_key: ReturnKey,
    /// Keyboard auto-capitalization. Defaults to
    /// [`Sentences`](AutoCapitalize::Sentences); set
    /// [`None`](AutoCapitalize::None) for handles / emails / URLs.
    #[prop(default = AutoCapitalize::Sentences)]
    auto_capitalize: AutoCapitalize,
    /// Automatic typo replacement as the user types. Defaults to `true`
    /// (the platform standard for prose); set `false` for handles /
    /// emails / URLs / any case- or spelling-sensitive identifier.
    ///
    /// iOS maps this to `UITextField.autocorrectionType` (`true` →
    /// `.default`, `false` → `.no`); Android to the `inputType`
    /// `TYPE_TEXT_FLAG_AUTO_CORRECT` flag.
    #[prop(default = true)]
    autocorrect: bool,
    /// Spelling / suggestion assistance — the iOS red-underline spell
    /// check and the Android keyboard suggestion strip. Defaults to
    /// `true`; set `false` to suppress both for identifier fields.
    ///
    /// iOS maps this to `UITextField.spellCheckingType` (`true` →
    /// `.default`, `false` → `.no`); Android to the *inverse* of the
    /// `inputType` `TYPE_TEXT_FLAG_NO_SUGGESTIONS` flag.
    #[prop(default = true)]
    spell_check: bool,
    /// Cursor color (CSS color string).
    caret_color: Option<Signal<String>>,
    /// Placeholder text color (CSS color string). Defaults to `#999999` on every Host.
    placeholder_color: Option<Signal<String>>,
    /// Selection-highlight color (CSS color string).
    selection_color: Option<Signal<String>>,
    /// Standard structured Whisker style.
    style: Option<Style>,
    /// Imperative handle ([`InputRef`]).
    input_ref: Option<InputRef>,
) -> Element {
    // Priority: `text` (two-way) → `value` (controlled) → empty, fed down as
    // a `Signal::Dynamic` so an external write re-applies natively. No
    // cursor-jump / echo guard is needed here: the native view only re-sets
    // its displayed text when the incoming value differs from what it shows.
    let value_prop: Signal<String> = {
        Signal::Dynamic(computed(move || {
            if let Some(t) = text {
                t.get()
            } else if let Some(v) = &value {
                v.get()
            } else {
                String::new()
            }
        }))
    };

    // Update the bound `text` signal BEFORE calling the user's `on_input`, so
    // reads inside that callback already see the new value.
    let on_input_cb = {
        move |ev: InputEvent| {
            let new = ev.into_value();
            if let Some(t) = text {
                t.set(new.clone());
            }
            if let Some(cb) = on_input {
                cb.run(new);
            }
        }
    };
    let on_change_cb = {
        move |ev: InputEvent| {
            if let Some(cb) = on_change {
                cb.run(ev.into_value());
            }
        }
    };
    // Mint an internal handle when the caller passed none, so the field still
    // registers itself in the focused-element registry below.
    let element_ref = input_ref
        .as_ref()
        .map(|h| h.r())
        .unwrap_or_else(ElementRef::new);

    let on_focus_cb = {
        move || {
            // `whisker-router` reads this registry to blur/restore this exact
            // input across a navigation.
            whisker::focus::note_focused(element_ref);
            if let Some(cb) = on_focus {
                cb.call();
            }
        }
    };
    let on_blur_cb = {
        move || {
            whisker::focus::note_blurred(element_ref);
            if let Some(cb) = on_blur {
                cb.call();
            }
        }
    };
    let on_submit_cb = {
        move |ev: InputEvent| {
            if let Some(cb) = on_submit {
                cb.run(ev.into_value());
            }
        }
    };

    let placeholder_prop: Signal<String> = placeholder.unwrap_or_default();
