/// - `color` — CSS-style colour applied to any `fill="currentColor"` /
///   `stroke="currentColor"` paint inside the SVG. Defaults to the
///   host's inherited foreground colour.
/// - `style` — structured Whisker CSS declarations for the host
///   `<view>`. Width / height MUST be set here (or via flex), the
///   replayer scales the SVG's viewBox to fill these bounds with
///   `preserveAspectRatio="xMidYMid meet"` semantics.
#[component]
pub fn svg(content: Signal<String>, color: Signal<String>, style: Style) -> Element {
    let display_list = computed(move || encode(&content.get()));

    render! {
        SvgRenderer(
            display_list: display_list,
            color: color,
            style: style.clone(),
        )
    }
}

/// Internal `module_element` — the platform-side `WhiskerSvgView`
/// receives `display_list` (base64 of the binary SPEC bytes),
/// `color` (CSS colour string for tint substitution), and the
/// standard `style:` cascade. Users don't touch this directly;
/// it's hidden behind the `Svg` wrapper above.
///
/// The leading underscore on `display_list` is a convention to
/// signal "internal transport, not a user-facing API surface".
/// (Whisker doesn't enforce visibility on Prop names yet — this
/// is documentation-level.)
#[whisker::module_element(
    name = "whisker-svg:Svg",
    measurement = None,
)]
pub fn svg_renderer(display_list: Signal<String>, color: Signal<String>, style: Style) {}


/// Reactive accessor for the current host view's safe-area insets.
///
/// Calls within the currently entered runtime share one signal and native
/// subscription. The initial value is [`SafeAreaInsets::default()`]; mobile
/// Hosts push the current insets when observation starts and whenever they
/// change. Web and desktop always expose the all-zero value.
///
/// The `Copy` handle belongs to the Runtime cache owner, so disposing
/// a component or route does not invalidate other readers. It must not be
/// retained across runtime shutdown or used in a different runtime.
///
/// **Must be called on the runtime's UI thread with that runtime entered.**
pub fn safe_area_insets() -> ReadSignal<SafeAreaInsets> {
    INSETS.with(|slot| slot.read)
}

struct Slot {
    read: ReadSignal<SafeAreaInsets>,
    _subscription: Option<ModuleSubscription>,
}

impl Slot {
    fn new(subscribe: impl FnOnce(RwSignal<SafeAreaInsets>) -> Option<ModuleSubscription>) -> Self {
        let signal = RwSignal::new(SafeAreaInsets::default());
        Self {
            read: signal.read_only(),
            _subscription: subscribe(signal),
        }
    }
}

whisker::runtime_local! {
    static INSETS: Slot = {
        #[cfg(any(target_os = "android", target_os = "ios"))]
        { Slot::new(subscribe_to_native) }
        #[cfg(not(any(target_os = "android", target_os = "ios")))]
        { Slot::new(|_| None) }
    };
}
