            AnimationTarget::Keyframes(keyframes) => (keyframes.name().to_owned(), Some(keyframes)),
            AnimationTarget::Name(name) => (name, None),
        };
        Self {
            name,
            keyframes,
            duration: None,
            timing: None,
            delay: None,
