                            selected.set(i);
                        }
                    },
                ) {
                    Text(value: label, max_lines: 1u32, style: label_style)
                }
            }
        })
        .collect();
    render! {
        View(style: col().margin_top(px(24)).padding((px(0), px(16)))) {
            View(style: row().padding_bottom(px(12))) {
                Text(value: format!("{}: ", option.name), style: text(15.0, 600, TEXT))
