#[component]
pub fn cart() -> Element {
    let state = use_context::<AppState>().expect("AppState");
    let nav = use_navigator();
    let insets = safe_area_insets();
    let lines = computed(move || {
        state.cart.with(|c| {
            c.as_ref()
                .map(|c| c.lines().iter().cloned().enumerate().collect::<Vec<_>>())
                .unwrap_or_default()
        })
