import XCTest
final class SearchScroll: XCTestCase {
    func testScroll() {
        let app = XCUIApplication(bundleIdentifier: "dev.whiskerrs.shopbench.whisker")
        app.terminate(); app.launch()
        app.descendants(matching: .any)["tab-search"].tap()
        let f = app.textFields["search-input"]; XCTAssertTrue(f.waitForExistence(timeout: 10))
        f.tap(); f.typeText("shirt")
        XCTAssertTrue(app.descendants(matching: .any)["search-result-0"].waitForExistence(timeout: 20))
        let list = app.descendants(matching: .any)["search-results"]
        print("FLOW: list frame \(list.frame)")
        for i in 0..<14 {
            list.swipeUp(velocity: .fast)
            let q = app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'search-result-'"))
            var ids: [Int] = []
            for k in 0..<q.count { if let n = Int(q.element(boundBy: k).identifier.dropFirst(14)) { ids.append(n) } }
            print("FLOW: swipe \(i) ids \(ids.min() ?? -1)...\(ids.max() ?? -1)")
        }
        try? XCUIScreen.main.screenshot().pngRepresentation.write(to: URL(fileURLWithPath: "/tmp/everbloom-search.png"))
    }
}
EOF
