            let q = app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'search-result-'"))
            var v: [Int] = []; for k in 0..<q.count { if let n = Int(q.element(boundBy: k).identifier.dropFirst(14)) { v.append(n) } }
            return "\(v.min() ?? -1)...\(v.max() ?? -1) kb=\(app.keyboards.count)"
        }
        print("FLOW: hittable=\(list.isHittable)")
        for i in 0..<3 { list.swipeUp(); print("FLOW: default swipe \(i) \(ids())") }
        for i in 0..<3 { list.swipeUp(velocity: .fast); print("FLOW: fast swipe \(i) \(ids())") }
        app.swipeUp(); print("FLOW: app swipe \(ids())")
    }
}
EOF
